struct CTCCreatureModeManager { long mode; bool HasMode(long m) { return m == mode; } };
struct CTCKrakenTentacle { long m_riseFrame; };

struct CAIStateGroup_KrakenTentacleRise {
    CAIBrain* PBrain;
    bool IsRunnable()
    {
